// PROPOSED A: fetch.jet; run against a trusted localhost TLS endpoint.
package: { name: "fetch", authority: { allow: [Net, Time, Rand, Env, FS.Read] } }
use { http: core.http }
run: fn() {
    page: http.get("https://localhost:18443/") ?? panic("fetch")
    print(page.status)
}
// Proposed: allow Net alone or add deny FS/Rand/Env -> E0749.
// A !FS.Read("secrets/") function row builds for a dynamic CA path.
// SSL_CERT_FILE inside secrets/ -> permission refusal before content read.
// Written allow acknowledges effects; no default notice is promised.

// PROPOSED A: serve.jet, a separate file.
package: { name: "hello_tls", authority: { allow: [Net, FS.Read, Time, Rand] } }
use { files: core.files, server: core.http.server }
run: fn() {
    cert: files.read("server.pem") ?? panic("certificate")
    key: files.read("server.key") ?? panic("key")
    mux: server.mux()
    mux.get("/", (_request: HTTPRequest) -> Ok(server.response(200, "hello")))
    listener: server.bind("127.0.0.1:18444", mux, tls: server.tls(cert, key)) ?? panic("bind")
    _: listener.serve() ?? panic("serve")
}
// Proposed: deny Rand -> E0749, not a running server.
// The current server path loads no system CA bundle.

