package: { name: "fetch", authority: { allow: [Net, Time, Rand, Env, FS.Read] } }
use { http: core.http, tls: core.net.tls }
run: fn() {
    cfg: tls.ClientConfig{host_reads: .Only([String]{"Time", "Rand.Draw", "Env", "FS.Read"})}
    page: http.get("https://localhost:18443/", tls: cfg) ?? panic("fetch")
    print(page.status)
